import 'dart:convert';import 'dart:io';import 'package:flutter_test/flutter_test.dart';import 'package:mobiarmy_flutter/features/gameplay/data/character/equipment_manifest_parser.dart';import 'package:mobiarmy_flutter/features/gameplay/domain/character/character_animation_state.dart';import 'package:mobiarmy_flutter/features/gameplay/domain/character/character_appearance.dart';import 'package:mobiarmy_flutter/features/gameplay/domain/character/character_definition.dart';import 'package:mobiarmy_flutter/features/gameplay/domain/character/equipment_definition.dart';import 'package:mobiarmy_flutter/features/gameplay/game/player/character_animation_controller.dart';
void main(){test('equipment geometry preserves offsets',(){final source=File('assets/manifests/equipment_manifest.example.json').readAsStringSync();final e=const EquipmentManifestParser().parse(source).single;expect(e.slot,EquipmentSlot.gun);expect(e.frames.first.offsetX,-18);expect(e.frames[1].height,13);});test('appearance update is immutable',(){final a=CharacterAppearance(characterType:0,equipmentIds:{EquipmentSlot.gun:5});final b=a.equip(EquipmentSlot.hat,3);expect(a[EquipmentSlot.hat],isNull);expect(b[EquipmentSlot.hat],3);});test('animation is delta-time based',(){final c=CharacterAnimationController(framesPerKind:{CharacterAnimationKind.walk:4},secondsPerFrame:0.1);final next=c.update(const CharacterAnimationState(kind:CharacterAnimationKind.walk),0.25);expect(next.frame,2);expect(next.elapsed,closeTo(0.05,0.0001));});test('layer order mirrors legacy PlayerEquip paint order',(){expect([EquipmentSlot.gun,EquipmentSlot.wing,EquipmentSlot.hat,EquipmentSlot.armor,EquipmentSlot.glasses].map((e)=>e.name),['gun','wing','hat','armor','glasses']);});}
